using System;
using System.Linq;
using System.Collections.Generic;
using System.Text.Json;
using Deception.Core;
using Deception.PolyModAdapter;
using U=Polytopia.Data.UnitData.Type;
namespace Deception.Tests
{
 public static partial class OrdinaryActionTests
 {
  static int Assertions;static readonly List<string> Tests=new();
  static void Check(bool b,string why){Assertions++;if(!b)throw new Exception(why);}
  static void Test(string id,Action a){try{a();Tests.Add(id);}catch(Exception e){throw new Exception(id,e);}}
  sealed class World
  {
   internal GameState State=new();internal PlayerState Player=new(){Id=1,FreeSpirit=true};internal UnitState Unit;internal TileData Tile;
   internal World(U type=U.dcp_spy,int paid=8,bool known=true)
   {
    OrdinaryActionEligibility.Clear();NativeInvestment.Clear();NativeRogueRules.Clear();NativeRegroupSession.Enabled=true;RecruitmentHooks.Register(Array.Empty<RecruitmentForm>(),new Dictionary<string,NativeAppearanceRoster>());OrdinaryActionEligibility.Install(new());
    Unit=new(){type=type,UnitData=new(){type=type,Cost=type is U.dcp_spy or U.dcp_spymaid?8:20},health=RecruitmentCatalog.IsMimicId(type.ToString())?10:100};
    Tile=new(){coordinates=Unit.coordinates,unit=Unit};State.Map.Tiles[Tile.coordinates]=Tile;State.Players[1]=Player;State.Players[2]=new(){Id=2,FreeSpirit=true};NativeRegroupSession.States.Add(State);
    bool mimic=RecruitmentCatalog.IsMimicId(type.ToString());
    var app=new LedgerAppearance("warrior",new("imperius","default"),new("imperius","default"),new("imperius","default"),0x123456,100,100,false,ApparentConcealment.Visible,-1,Array.Empty<string>());
    Write(new(new Guid("00112233-4455-6677-8899-aabbccddeeff"),2,1,new[]{new LedgerUnit(1,1,true,mimic?LedgerActualKind.Mimic:LedgerActualKind.Genuine,mimic,mimic?app:null,known?PaidInvestmentKind.Known:PaidInvestmentKind.UnknownLegacy,known?paid:0)},Array.Empty<LedgerReceipt>()));
   }
   internal NativeIdentityLedger Read(){var s=NativeGameStateEnvelope.Get(State)!;return NativeIdentityLedgerCodec.Decode(s.Bytes(),s.Revision);}
   internal void Write(NativeIdentityLedger l)=>NativeGameStateEnvelope.Set(State,0,NativeIdentityLedgerCodec.Encode(l,0));
   internal void Rogue(){var l=Read();Write(l with{Units=l.Units.Select(x=>x with{Rogue=new(1,2,State.CurrentTurn)}).ToArray()});Unit.owner=2;State.CurrentPlayer=2;}
   internal void Return(){State.CurrentPlayer=1;new StartTurnAction{PlayerId=1}.Execute(State);}
   internal DisbandCommand Disband()=>new(1,Tile.coordinates);
   internal CaptureCommand Capture()=>new(){PlayerId=1,Coordinates=Tile.coordinates,UnitId=1};
   internal object[] Menu()=>Native.Items(CommandUtils.GetUnitActions(State,Player,Tile,false)).ToArray();
  }
  public static int Run()
  {
   try
   {
    foreach(U species in new[]{U.dcp_spy,U.dcp_spymaid,U.dcp_motherfogger,U.dcp_mimic_form_warrior,U.dcp_mermimic})
    {
     Test("ORD-capture-completes-"+species,()=>{var w=new World(species);Check(!w.Unit.CanAttack(),"ordinary offense enabled");Check(UnitDataExtensions.CanCapture(w.Unit,w.State,w.Tile,false,true),"ready neutral capture predicate denied");Check(w.Menu().OfType<CaptureCommand>().Count()==1,"native capture command absent");var c=w.Capture();Check(c.IsValid(w.State,out _),"native command validation denied");c.Execute(w.State);w.State.Drain();Check(w.Tile.owner==1&&w.Unit.home==w.Tile.coordinates&&w.Unit.moved&&w.Unit.attacked,"native city/home/action completion missing");Check(!w.Unit.CanAttack(),"predicate readiness leaked into offense");});
     Test("ORD-disband-completes-"+species,()=>{int paid=species is U.dcp_spy or U.dcp_spymaid?8:3;var w=new World(species,paid);var menu=w.Menu();Check(menu.OfType<DisbandCommand>().Count()==1,"native disband command absent");Check(!Native.Items(CommandUtils.LastNative!).OfType<DisbandCommand>().Any(),"cached native list mutated");int before=w.Player.Currency;var c=menu.OfType<DisbandCommand>().Single();Check(c.IsValid(w.State,out _),"disband command validation denied");c.Execute(w.State);Check(w.Tile.unit==w.Unit&&w.Player.Currency==before,"command performed action or refund prematurely");w.State.Drain();Check(w.Tile.unit is null&&w.Player.Currency==before+paid/2,"native queued removal/refund mismatch");});
     Test("ORD-returned-rogue-"+species,()=>{var w=new World(species);w.Rogue();Check(NativeRogueRules.IsRogue(w.State,w.Unit),"active Rogue absent");w.Unit.moved=w.Unit.attacked=true;w.Return();Check(w.Unit.owner==1&&!w.Unit.moved&&!w.Unit.attacked&&!NativeRogueRules.IsRogue(w.State,w.Unit),"real AfterStart failed to clear cached Rogue/readiness");Check(UnitDataExtensions.CanCapture(w.Unit,w.State,w.Tile,false,true)&&w.Menu().OfType<DisbandCommand>().Count()==1,"returned Rogue still banned");w.Capture().Execute(w.State);w.State.Drain();Check(w.Tile.owner==1,"returned Rogue capture incomplete");w.Unit.moved=w.Unit.attacked=false;var c=w.Disband();c.Execute(w.State);w.State.Drain();Check(w.Tile.unit is null,"returned Rogue native disband incomplete");});
     foreach(string deny in new[]{"moved","attacked","frozen","leader","no-tech","active-rogue"})Test("ORD-disband-denial-"+species+"-"+deny,()=>{var w=new World(species);if(deny=="moved")w.Unit.moved=true;if(deny=="attacked")w.Unit.attacked=true;if(deny=="frozen")w.Unit.effects.Add(UnitEffect.Frozen);if(deny=="leader")w.Unit.Leader=true;if(deny=="no-tech")w.Player.FreeSpirit=false;if(deny=="active-rogue")w.Rogue();var c=w.Disband();Check(!w.Menu().OfType<DisbandCommand>().Any()&&!c.IsValid(w.State,out _),"ineligible disband offered/validated");int cash=w.Player.Currency;c.Execute(w.State);var a=new DisbandUnitAction{PlayerId=1,Coordinates=w.Tile.coordinates,GetPaid=true};w.State.ActionStack.Add(a);w.State.Drain();Check(w.Tile.unit==w.Unit&&w.Player.Currency==cash,"direct or queued invalid disband removed/refunded");});
     foreach(string deny in new[]{"moved","attacked","frozen","leader","peace","active-rogue"})Test("ORD-capture-denial-"+species+"-"+deny,()=>{var w=new World(species);if(deny=="moved")w.Unit.moved=true;if(deny=="attacked")w.Unit.attacked=true;if(deny=="frozen")w.Unit.effects.Add(UnitEffect.Frozen);if(deny=="leader")w.Unit.Leader=true;if(deny=="peace")w.Player.Peace=true;if(deny=="active-rogue")w.Rogue();Check(!UnitDataExtensions.CanCapture(w.Unit,w.State,w.Tile,false,true),"native/Rogue capture condition bypassed");w.Capture().Execute(w.State);w.State.Drain();Check(w.Tile.owner==0,"invalid direct capture completed");});
    }
    foreach(U species in new[]{U.dcp_spy,U.dcp_mimic_form_warrior})Test("ORD-returned-rogue-no-free-spirit-"+species,()=>{var w=new World(species);w.Rogue();w.Return();w.Player.FreeSpirit=false;Check(UnitDataExtensions.CanCapture(w.Unit,w.State,w.Tile,false,true)&&!w.Disband().IsValid(w.State,out _),"returned capture/disband incorrectly share research permission");w.Disband().Execute(w.State);w.State.Drain();Check(w.Tile.unit==w.Unit&&w.Player.Currency==20,"returned Rogue disband bypassed Free Spirit");});
    Test("ORD-vessel-cargo-genuine-investment",()=>{var w=new World(U.transportship,13);var cargo=new UnitState{id=2,type=U.warrior,UnitData=new(){Cost=99}};w.Unit.passengerUnit=cargo;w.Unit.UnitData.Cost=20;int native=w.Unit.GetFullCost(w.State);w.Disband().Execute(w.State);w.State.Drain();Check(native==119&&w.Player.Currency==26&&w.Tile.unit is null,"native cargo price or apparent vessel price inflated genuine thirteen-star investment");Check(cargo.UnitData.Cost==99&&cargo.health==100&&cargo.owner==1,"refund mutated cargo stats/ownership");});
    Test("ORD-stale-menu-rechecks-research",()=>{var w=new World();var c=w.Menu().OfType<DisbandCommand>().Single();w.Player.FreeSpirit=false;Check(!c.IsValid(w.State,out _),"stale research accepted");c.Execute(w.State);w.State.Drain();Check(w.Tile.unit==w.Unit&&w.Player.Currency==20,"stale menu changed economy");});
    foreach(string context in new[]{"unbound","ended","wrong-actor","hidden","dead","pending"})Test("ORD-command-context-"+context,()=>{var w=new World();if(context=="unbound")NativeRegroupSession.States.Remove(w.State);if(context=="ended")w.State.CurrentState=GameState.State.Ended;if(context=="wrong-actor")w.State.CurrentPlayer=2;if(context=="hidden")w.Tile.Explored=false;if(context=="dead")w.Unit.health=0;if(context=="pending")w.State.Pending=true;var c=w.Disband();Check(!c.IsValid(w.State,out _),"invalid context validated");c.Execute(w.State);w.Capture().Execute(w.State);w.State.Drain();Check(w.Tile.unit==w.Unit&&w.Tile.owner==0&&w.Player.Currency==20,"invalid context mutated board/economy");});
    Test("ORD-ready-enrolled-sibling-action",()=>{var w=new World(U.dcp_mermimic,3);w.Disband().Execute(w.State);var original=w.State;var sibling=new GameState{Map=w.State.Map,CurrentCommand=w.State.CurrentCommand,ActionStack=w.State.ActionStack};sibling.Players[1]=w.Player;sibling.Players[2]=original.Players[2];NativeRegroupSession.States.Add(sibling);var snapshot=NativeGameStateEnvelope.Get(original)!;NativeGameStateEnvelope.Set(sibling,snapshot.Revision,snapshot.Bytes());w.State=sibling;sibling.Drain();Check(w.Tile.unit is null&&w.Player.Currency==21,"enrolled copied state lost queued disband/refund");});
    Test("ORD-active-rogue-unpaid-elimination-preserved",()=>{var w=new World();w.Rogue();var a=new DisbandUnitAction{PlayerId=1,Coordinates=w.Tile.coordinates,GetPaid=false};w.State.ActionStack.Add(a);w.State.Drain();Check(w.Tile.unit is null&&w.Player.Currency==20,"unpaid elimination blocked or paid");});
    Test("ORD-disband-no-unscoped-action",()=>{var w=new World();new DisbandUnitAction{PlayerId=1,Coordinates=w.Tile.coordinates,GetPaid=true}.Execute(w.State);Check(w.Tile.unit==w.Unit&&w.Player.Currency==20,"unscoped paid action removed unit");});
    Test("ORD-unknown-investment-native-fallback",()=>{var w=new World(U.dcp_mimic_form_giant,0,false);w.Unit.UnitData.Cost=RecruitmentCatalog.Cost;w.Disband().Execute(w.State);w.State.Drain();Check(w.Player.Currency==20&&w.Tile.unit is null,"legacy investment guessed or no native fallback");});
    Test("ORD-free-apparent-upgrade-cannot-inflate-refund",()=>{var w=new World(U.dcp_mimic_form_giant,3);w.Unit.UnitData.Cost=40;int outside=w.Unit.GetFullCost(w.State);w.Disband().Execute(w.State);w.State.Drain();Check(outside==40&&w.Player.Currency==21,"free carrier value inflated refund or leaked cost query");});
    Test("ORD-one-star-mimic-and-historical-investment-refunds",()=>{foreach(var type in new[]{U.dcp_mimic_form_warrior,U.dcp_mermimic})foreach(int paid in new[]{1,3}){var w=new World(type,paid);w.Unit.UnitData.Cost=RecruitmentCatalog.Cost;w.Write(NativeIdentityLedgerCodec.Decode(NativeIdentityLedgerCodec.Encode(w.Read(),0),0));var action=w.Disband();action.Execute(w.State);w.State.Drain();Check(w.Tile.unit is null&&w.Player.Currency==20+paid/2,"current catalog price replaced saved actual investment or one-star refund was rounded up");}});
    Test("ORD-real-paid-upgrade-adds-investment",()=>{var w=new World(U.warrior,3);var a=new UpgradeAction{PlayerId=1,Coordinates=w.Tile.coordinates,Cost=5};NativeInvestment.BeforeUpgrade(a,w.State,out var scope);w.Player.Currency-=5;w.Unit.type=U.transportship;w.Unit.UnitData.Cost=99;NativeInvestment.AfterPurchase(scope,true);Check(w.Read().Units[0].PaidStars==8,"actual payment missing from investment");w.Disband().Execute(w.State);w.State.Drain();Check(w.Tile.unit is null&&w.Player.Currency==19,"paid vessel refund should be four stars");});
    Test("ORD-cost-exact-body-and-native-single-star-children",()=>{var w=new World(U.dcp_spy,8);var other=new UnitState{type=U.warrior,UnitData=new(){Cost=99}};var a=new DisbandUnitAction{PlayerId=1,Coordinates=w.Tile.coordinates,GetPaid=true};w.State.ActionStack.Add(a);NativeInvestment.BeforeDisband(a,w.State,out var scope);Check(w.Unit.GetFullCost(w.State)==8&&other.GetFullCost(w.State)==99,"cost authority escaped exact body");NativeInvestment.DisbandFinished(null,scope);a.Execute(w.State);var rewards=Native.Items(w.State.ActionStack).OfType<IncreaseCurrencyAction>().ToArray();Check(rewards.Length==4&&rewards.All(x=>x.Amount==1),"refund rewrite multiplied native one-star rewards");});
    Test("ORD-cost-snapshot-change-invalidates",()=>{var w=new World(U.dcp_spy,8);w.Unit.UnitData.Cost=12;var a=new DisbandUnitAction{Coordinates=w.Tile.coordinates,GetPaid=true};w.State.ActionStack.Add(a);NativeInvestment.BeforeDisband(a,w.State,out var scope);w.Write(w.Read());Check(w.Unit.GetFullCost(w.State)==12,"old snapshot refund scope reused");NativeInvestment.DisbandFinished(null,scope);});
    Test("ORD-cost-error-and-clear-unwind",()=>{var w=new World(U.dcp_spy,8);w.Unit.UnitData.Cost=12;var a=new DisbandUnitAction{Coordinates=w.Tile.coordinates,GetPaid=true,ThrowBeforeCost=true};w.State.ActionStack.Add(a);try{a.Execute(w.State);}catch(InvalidOperationException){}Check(w.Unit.GetFullCost(w.State)==12,"exception leaked refund scope");NativeInvestment.BeforeDisband(a,w.State,out var scope);NativeInvestment.Clear();NativeInvestment.DisbandFinished(null,scope);Check(w.Unit.GetFullCost(w.State)==12,"late finalizer revived cleared scope");});
    Test("ORD-predicate-nesting-clear-and-offense",()=>{var w=new World();OrdinaryActionEligibility.EnterCapture(w.Unit,out var outer);Check(w.Unit.CanAttack(),"native scoped readiness missing");var other=new UnitState{type=U.warrior};OrdinaryActionEligibility.EnterCapture(other,out var inner);Check(!w.Unit.CanAttack(),"nested foreign query borrowed readiness");OrdinaryActionEligibility.ExitPredicate(null,inner);Check(w.Unit.CanAttack(),"nested scope did not restore");Check(!UnitDataExtensions.CanAttackAnything(w.Unit,1,w.State)&&!BattleHelpers.CanDefenderRetaliate(w.State,other,w.Unit),"scope granted offense/retaliation");OrdinaryActionEligibility.Clear();OrdinaryActionEligibility.ExitPredicate(null,outer);Check(!w.Unit.CanAttack(),"Clear/finalizer restored old offense exception");});
    Test("ORD-native-command-list-deduplicates",()=>{var w=new World();object list=w.Menu().Aggregate(new Il2CppSystem.Collections.Generic.List<CommandBase>(),(l,o)=>{l.Add((CommandBase)o);return l;});var before=list;NativeOrdinaryCommands.DisbandMenu(w.State,w.Player,w.Tile,ref list);Check(ReferenceEquals(before,list)&&Native.Items(list).OfType<DisbandCommand>().Count()==1,"duplicate native command or unnecessary replacement");});
    Test("ORD-native-ordinary-unit-passthrough",()=>{var w=new World(U.warrior,2);var list=CommandUtils.GetUnitActions(w.State,w.Player,w.Tile,false);Check(Native.Items(list).OfType<DisbandCommand>().Count()==1&&ReferenceEquals(list,CommandUtils.LastNative),"ordinary native action lost or its list replaced");Check(w.Unit.CanAttack(),"ordinary offense suppressed");});
    Test("ORD-safe-native-hook-ABI",()=>{var h=new HarmonyLib.Harmony();NativeOrdinaryCommands.Install(h);NativeInvestment.Install(h);Check(h.Hooks.Count==9&&h.Hooks.All(m=>!m.GetParameters().Any(p=>p.ParameterType.BaseType?.FullName=="Il2CppSystem.ValueType")),"hook signature changed or unsafe wrapper ABI");});
    SpyStealthCases();
    var result=new{passed=true,cases=Tests.Count,assertions=Assertions,tests=Tests,nativeGame="NOT RUN"};Console.WriteLine(JsonSerializer.Serialize(result));return 0;
   }catch(Exception e){Console.WriteLine(e);return 1;}finally{NativeInvestment.Clear();OrdinaryActionEligibility.Clear();NativeRogueRules.Clear();}
  }
 }
}
